import { PageData, BuildOptions } from "./types";

export interface Plugin {
  name: string;
  onStart?(options: BuildOptions): Promise<void>;
  beforeBuild?(options: BuildOptions): Promise<void>;
  onFile?(page: PageData, options: BuildOptions): Promise<PageData>;
  afterBuild?(options: BuildOptions, pages: PageData[]): Promise<void>;
  onEnd?(options: BuildOptions): Promise<void>;
}

export async function runHook(
  plugins: Plugin[],
  hook: "onStart" | "beforeBuild" | "afterBuild" | "onEnd",
  options: BuildOptions,
  pages?: PageData[]
): Promise<void> {
  for (const plugin of plugins) {
    const fn = plugin[hook];
    if (fn) {
      if (hook === "afterBuild" && pages !== undefined) {
        await fn.call(plugin, options, pages);
      } else {
        await fn.call(plugin, options);
      }
    }
  }
}

export async function runFilePipeline(
  plugins: Plugin[],
  page: PageData,
  options: BuildOptions
): Promise<PageData> {
  let current = page;
  for (const plugin of plugins) {
    if (plugin.onFile) {
      current = await plugin.onFile(current, options);
    }
  }
  return current;
}

import { promises as fs } from "fs";
import path from "path";
import matter from "gray-matter";
import yaml from "js-yaml";
import MarkdownIt from "markdown-it";
import { PageData, BuildOptions, Frontmatter } from "../types";
import { Plugin } from "../plugin";

const matterOptions = {
  engines: {
    yaml: {
      parse: (input: string) => yaml.load(input, { schema: yaml.FAILSAFE_SCHEMA }) as Record<string, unknown>,
    },
  },
};

export function createMarkdownPlugin(): Plugin {
  const md = new MarkdownIt();

  return {
    name: "markdown",

    async onFile(page: PageData, options: BuildOptions): Promise<PageData> {
      const contentDir = path.resolve(options.contentDir);
      const absPath = path.join(contentDir, page.path);
      const raw = await fs.readFile(absPath, "utf-8");
      const { data, content } = matter(raw, matterOptions);
      const html = md.render(content);

      const frontmatter: Frontmatter = {};
      for (const [key, value] of Object.entries(data)) {
        frontmatter[key] = String(value ?? "");
      }

      return { path: page.path, frontmatter, html };
    },
  };
}

const mdSingleton = new MarkdownIt();

export async function parseMarkdownFile(
  contentDir: string,
  filePath: string
): Promise<PageData> {
  const absPath = path.join(contentDir, filePath);
  const raw = await fs.readFile(absPath, "utf-8");
  const { data, content } = matter(raw, matterOptions);
  const html = mdSingleton.render(content);

  const frontmatter: Frontmatter = {};
  for (const [key, value] of Object.entries(data)) {
    frontmatter[key] = String(value ?? "");
  }

  return { path: filePath, frontmatter, html };
}

import { Plugin } from "../plugin";
import { PageData, BuildOptions } from "../types";
import { createTemplateEngine, TemplateEngine } from "../template-engine";
import path from "path";
import { generatePageHtml, generateIndexHtml } from "../index";

export function createTemplatePlugin(): Plugin {
  let engine: TemplateEngine | null = null;

  return {
    name: "template",

    async beforeBuild(options: BuildOptions): Promise<void> {
      const templatesDir = options.templatesDir
        ? path.resolve(options.templatesDir)
        : path.resolve("templates");
      engine = await createTemplateEngine(templatesDir);
    },

    async onFile(page: PageData, _options: BuildOptions): Promise<PageData> {
      let pageHtml: string;
      if (engine) {
        pageHtml = engine.renderPage(page.frontmatter, page.html);
      } else {
        pageHtml = generatePageHtml(page);
      }
      return { path: page.path, frontmatter: page.frontmatter, html: pageHtml };
    },

    async afterBuild(options: BuildOptions, pages: PageData[]): Promise<void> {
      let indexHtml: string;
      if (engine) {
        indexHtml = engine.renderIndex(pages);
        if (!indexHtml) {
          indexHtml = generateIndexHtml(pages);
        }
      } else {
        indexHtml = generateIndexHtml(pages);
      }

      const outputDir = path.resolve(options.outputDir);
      const { promises: fs } = await import("fs");
      await fs.writeFile(path.join(outputDir, "index.html"), indexHtml, "utf-8");
    },
  };
}

import { Plugin } from "../plugin";
import { BuildOptions } from "../types";
import http from "http";
import { promises as fs } from "fs";
import path from "path";
import chokidar from "chokidar";
import { WebSocketServer, WebSocket } from "ws";
import { build } from "../index";

const MIME_TYPES: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "application/javascript; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
  ".xml": "application/xml; charset=utf-8",
  ".txt": "text/plain; charset=utf-8",
};

function getMimeType(filePath: string): string {
  const ext = path.extname(filePath).toLowerCase();
  return MIME_TYPES[ext] || "application/octet-stream";
}

export function injectLiveReloadScript(html: string, port: number): string {
  const script = `<script>(function(){var ws=new WebSocket("ws://localhost:${port}/__livereload");ws.onmessage=function(m){if(m.data==="reload"){window.location.reload();}};})();</script>`;
  return html.replace("</body>", script + "</body>");
}

async function serveFile(
  filePath: string,
  res: http.ServerResponse,
  port: number
): Promise<void> {
  try {
    await fs.access(filePath);
    const stat = await fs.stat(filePath);

    if (stat.isDirectory()) {
      const indexPath = path.join(filePath, "index.html");
      try {
        await fs.access(indexPath);
        filePath = indexPath;
      } catch {
        res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
        res.end();
        return;
      }
    }

    let content = await fs.readFile(filePath);
    const ext = path.extname(filePath).toLowerCase();

    if (ext === ".html") {
      let html = content.toString("utf-8");
      html = injectLiveReloadScript(html, port);
      res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
      res.end(html, "utf-8");
    } else {
      res.writeHead(200, { "Content-Type": getMimeType(filePath) });
      res.end(content);
    }
  } catch {
    res.writeHead(404, { "Content-Type": "text/plain; charset=utf-8" });
    res.end("Not Found");
  }
}

export function createDevServerPlugin(): Plugin {
  return {
    name: "dev-server",
  };
}

export async function startDevServer(
  options: BuildOptions & { port: number }
): Promise<{ server: http.Server; wss: WebSocketServer; close: () => Promise<void> }> {
  const contentDir = path.resolve(options.contentDir);
  const outputDir = path.resolve(options.outputDir);
  const templatesDir = options.templatesDir
    ? path.resolve(options.templatesDir)
    : path.resolve("templates");
  const port = options.port;

  await build({
    contentDir,
    outputDir,
    templatesDir,
  });

  const server = http.createServer((req, res) => {
    if (!req.url) {
      res.writeHead(404);
      res.end();
      return;
    }

    const urlPath = req.url === "/" ? "/index.html" : req.url.split("?")[0];
    const filePath = path.join(outputDir, urlPath);
    serveFile(filePath, res, port);
  });

  const wss = new WebSocketServer({ server, path: "/__livereload" });

  let rebuildTimer: NodeJS.Timeout | null = null;
  const clients = new Set<WebSocket>();

  wss.on("connection", (ws) => {
    clients.add(ws);
    ws.on("close", () => {
      clients.delete(ws);
    });
  });

  async function doRebuild(): Promise<void> {
    try {
      await build({
        contentDir,
        outputDir,
        templatesDir,
      });
      for (const client of clients) {
        if (client.readyState === WebSocket.OPEN) {
          client.send("reload");
        }
      }
    } catch (err) {
      console.error("Rebuild error:", (err as Error).message);
    }
  }

  const watcher = chokidar.watch([contentDir, templatesDir], {
    ignoreInitial: true,
  });

  watcher.on("all", () => {
    if (rebuildTimer) {
      clearTimeout(rebuildTimer);
    }
    rebuildTimer = setTimeout(() => {
      rebuildTimer = null;
      doRebuild();
    }, 100);
  });

  return new Promise((resolve) => {
    server.listen(port, () => {
      console.log(`Dev server running at http://localhost:${port}/`);
      resolve({
        server,
        wss,
        close: async () => {
          await watcher.close();
          if (rebuildTimer) {
            clearTimeout(rebuildTimer);
          }
          wss.close();
          await new Promise<void>((r) => server.close(() => r()));
        },
      });
    });
  });
}

